import { test, expect } from '@playwright/test';

test.describe('Task Deletion with Confirmation Dialog', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/tasks');
  });

  test('should successfully delete a task after confirming deletion', async ({ page }) => {
    // Setup: Add a task to delete
    const taskInput = page.getByPlaceholder('Enter task description');
    await taskInput.fill('Complete the Playwright script');
    const addButton = page.getByRole('button', { name: /add task/i });
    await addButton.click();

    // Verify task exists
    const taskItem = page.getByText('Complete the Playwright script');
    await expect(taskItem).toBeVisible();

    // Get the delete button for the task
    const deleteButton = page.getByRole('button', { name: /delete/i });
    await deleteButton.click();

    // Verify confirmation dialog appears
    const confirmDialog = page.locator('[data-testid="confirm-dialog"]');
    await expect(confirmDialog).toBeVisible();
    await expect(confirmDialog).toContainText('Are you sure you want to delete this task?');

    // Confirm deletion
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await confirmButton.click();

    // Verify confirmation dialog closes
    await expect(confirmDialog).not.toBeVisible();

    // Verify task is removed from the list
    await expect(taskItem).not.toBeVisible();

    // Verify success message appears
    const successMessage = page.getByText('Task deleted successfully');
    await expect(successMessage).toBeVisible();
  });

  test('should cancel task deletion when user clicks cancel in confirmation dialog', async ({ page }) => {
    // Setup: Add a task to delete
    const taskInput = page.getByPlaceholder('Enter task description');
    await taskInput.fill('Review the Playwright script');
    const addButton = page.getByRole('button', { name: /add task/i });
    await addButton.click();

    // Verify task exists
    const taskItem = page.getByText('Review the Playwright script');
    await expect(taskItem).toBeVisible();

    // Get the delete button for the task
    const deleteButton = page.getByRole('button', { name: /delete/i });
    await deleteButton.click();

    // Verify confirmation dialog appears
    const confirmDialog = page.locator('[data-testid="confirm-dialog"]');
    await expect(confirmDialog).toBeVisible();

    // Cancel deletion
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await cancelButton.click();

    // Verify confirmation dialog closes
    await expect(confirmDialog).not.toBeVisible();

    // Verify task still exists
    await expect(taskItem).toBeVisible();

    // Verify no success message appears
    const successMessage = page.getByText('Task deleted successfully');
    await expect(successMessage).not.toBeVisible();
  });
});
